      rowClaudeQuotaCollection: "로컬 Claude 사용 정보 수집",
      rowClaudeQuotaCollectionDesc: "기본값은 꺼짐입니다. Clawd의 보이는 Claude Code 상태 표시줄로 보고된 컨텍스트 창과 사용 가능한 구독 쿼터를 읽습니다. 기존 사용자 상태 표시줄은 대체하지 않습니다. 끄면 Clawd 소유 상태 표시줄과 캐시된 로컬 Claude 쿼터를 제거하며, Remote SSH와 다른 제공자의 데이터는 유지합니다.",
